/**
 * Fastify 应用装配（T0-01）
 *
 * 只做三件事：注册统一错误处理器、集中注册路由、提供依赖注入缝隙。
 * 业务模块不得在这里 import 自己的 handler；统一走 routes.ts。
 *
 * ---------------------------------------------------------------------------
 * 【本次扩展】为什么新增 `prisma` 可选注入（T0 缺口修补）
 *
 * 契约「Testing Decisions → 唯一 seam」规定：**HTTP 接口层是唯一测试 seam**，
 * 且「越权用例必须打接口，不能用『前端不渲染按钮』代替」。
 *
 * 但原装配只有 `buildApp({ logger })`，而数据库来自 `src/db/client.ts` 的
 * **模块级单例**——该单例在首次构造时绑定当时的 `DATABASE_URL`，之后不再重新绑定
 * （见 test/db-client-isolation.test.ts 的探针结论）。
 *
 * 后果：`buildApp()` 构造出的 app 永远查单例，也就是**永远连 `.env` 的 dev.db**，
 * 无法指向测试用临时库。于是「打接口」的测试要么污染开发库，要么无法隔离。
 * 这是 T0 交付的真缺口：数据层可测（97 例），但 **HTTP 层没有注入缝隙**，
 * 导致契约要求的「接口层越权测试」在四个模块上都写不出来。
 *
 * 修补方式（**向后兼容，不改变任何既有行为**）：
 *   - 新增可选参数 `prisma`。**不传时行为与原先完全一致**（回落全局单例）。
 *   - 现有调用 `buildApp({ logger: false })` 与 `buildApp()` 均无需改动。
 *   - 测试改为 `buildApp({ prisma: tempDb.prisma })`，即可让 app 指向独立临时库。
 *
 * 本扩展不改动 `src/db/client.ts`（仍保持单例语义），不触碰 `AppError`、
 * 错误码表或任何既有签名，因此**不构成契约变更**；待模块负责人接管后可调整。
 * ---------------------------------------------------------------------------
 */
import Fastify, { type FastifyInstance } from 'fastify'
import type { Prisma, PrismaClient } from '@prisma/client'
import { registerErrorHandler } from './error-handler.js'
import { registerRoutes, type RouteContext } from './routes.js'
import { registerActorResolver } from './auth/actor.js'
import { prisma as defaultPrisma } from './db/client.js'
import { PrismaEventRepository, createEventAuthorizationPort } from './db/event-repository.js'
import { createGanttEventPort } from './modules/gantt/event-port.js'
import { createRequirementEventPort } from './modules/requirement/event-port.js'
import { createRiskEventPort } from './modules/risk/event-port.js'
import { createNotificationRuntime } from './db/notification-runtime.js'
import { createAcceptanceEventPort } from './modules/acceptance/event-port.js'
import { PrismaAiSuggestionRepository, createAiAuthorizationPort } from './db/ai-repository.js'
import { createDomainEventInfrastructure } from './modules/events/factory.js'
import { createAiBreakdownService } from './modules/ai/factory.js'
import { createPrismaAiStorySource } from './modules/ai/story-source.js'
import { createTaskStartGuardPort } from './modules/task/rules.js'
import type { RequirementBreakdownRecord } from './shared/ai.js'
import type {
  DomainEventPublisherPort,
  DomainEventQueryPort,
  DomainEventReplayPort,
  DomainEventSubscriberPort,
} from './shared/events.js'

/**
 * 挂到 Fastify 实例上的事件公共端口（业务域只依赖这些端口，不 import D 的 service）。
 *
 * 组装点唯一（`DECISIONS.md` `arch.shared-ports-and-assembly`）：仓储适配器、权限适配器、
 * D 的事件实现都在这里显式注入；生命周期由 `onReady` / `onClose` 驱动。
 */
export type EventPorts = {
  publisher: DomainEventPublisherPort
  subscriber: DomainEventSubscriberPort
  query: DomainEventQueryPort
  replay: DomainEventReplayPort
}

declare module 'fastify' {
  interface FastifyInstance {
    /** 领域事件公共端口（由 `buildApp` 组装注入）。 */
    events: EventPorts
  }
}

export type BuildAppOptions = {
  /** 是否开启 Fastify 日志。测试环境建议关闭，避免噪声。 */
  logger?: boolean
  /**
   * 数据库客户端注入点。
   *
   * 不传时回落到 `src/db/client.ts` 的全局单例（生产 / 本地开发路径）；
   * 测试传入 `createTempDatabase().prisma` 以使用独立临时库，避免污染 dev.db。
   */
  prisma?: PrismaClient
}

export function buildApp(options: BuildAppOptions = {}): FastifyInstance {
  const app = Fastify({
    logger: options.logger ?? process.env.NODE_ENV !== 'test',
  })

  // 不传 prisma 时与原先行为完全一致（回落单例）
  const context: RouteContext = { prisma: options.prisma ?? defaultPrisma }

  // #31 US-11 AI 建议：显式组装模型端口（本轮 `LOCAL_STUB`）、DB 仓储、统一鉴权适配器与只读
  // 故事来源，注入路由总表。业务域通过服务端口复用，不 import D 的 service（契约 I-9）。
  // 外部模式必须显式注入 adapter；配置错误直接阻止启动，禁止静默降级为桩。
  context.aiService = createAiBreakdownService({
    ai: { mode: 'LOCAL_STUB' },
    authorization: createAiAuthorizationPort(context.prisma),
    repository: new PrismaAiSuggestionRepository<RequirementBreakdownRecord>(context.prisma),
    storySource: createPrismaAiStorySource(context.prisma),
  })

  // #37 领域事件：显式注入 DB 仓储 + 统一鉴权适配器，组装 D 的事件实现。
  // 业务域通过 `app.events` 使用 publisher / query 端口，不 import D 的 service（契约 I-9）。
  // ★ 同一个 `PrismaEventRepository` 实例同时供 D 的基础设施与两个域内事件适配器使用：
  //   两套连接语义（同一 prisma 客户端）才不会出现「查询看不到域内写入」的裂缝。
  const eventRepository = new PrismaEventRepository(context.prisma)
  const infrastructure = createDomainEventInfrastructure({
    repository: eventRepository,
    authorization: createEventAuthorizationPort(context.prisma),
  })
  const events: EventPorts = {
    publisher: { publish: (input) => infrastructure.publish(input) },
    subscriber: { subscribe: (eventName, subscriberId, handler) =>
      infrastructure.subscribe(eventName, subscriberId, handler) },
    // ★ 组装层把 actor 注入 filter：D 的 service 原样透传给仓储，
    //   DB 适配器据此在**查询层**做对象级可见性过滤（契约 I-6）。
    query: { query: (actorUserId, query) => infrastructure.query(actorUserId, { ...query, actorUserId }) },
    replay: {
      redeliver: (actorUserId, eventId) => infrastructure.redeliver(actorUserId, eventId),
      replay: (actorUserId, query) => infrastructure.replay(actorUserId, { ...query, actorUserId }),
    },
  }
  app.decorate('events', events)

  // 业务域事件端口：域内适配器把草稿映射为信封，在**调用方事务**内追加（不自行提交）。
  // 与 D 的基础设施共用同一个仓储实例（见上）。
  context.ganttEvents = createGanttEventPort({ repository: eventRepository })
  context.requirementEvents = createRequirementEventPort({ repository: eventRepository })
  context.riskEvents = createRiskEventPort({ repository: eventRepository })
  context.acceptanceEvents = createAcceptanceEventPort({ repository: eventRepository })
  // #34 站内通知公共运行时：真实 DB 仓储 + 权威接收者解析器 + #37 订阅适配器 + 提交后消费桥接
  // + B 自己的定时生产点（task.overdue / milestone.due）。与事件基础设施共用**同一个**
  // `PrismaEventRepository` 实例（否则会出现「查询看不到域内写入」的裂缝）。D 的消费模块零改动。
  // 测试环境（NODE_ENV === 'test'）不自动启动后台定时器，避免 10s 扫描污染其它模块的事件计数；
  // 订阅注册与首次激活仍照常完成，HTTP 探测 / 生产则开启定时器。
  const notificationRuntime = createNotificationRuntime({
    prisma: context.prisma,
    subscriber: events.subscriber,
    eventRepository,
    autoStartLoops: process.env.NODE_ENV !== 'test',
    onError: (error, scope) => app.log.error({ err: error, scope }, '通知后台任务失败'),
  })
  context.notificationService = notificationRuntime.module.service

  // 生命周期：Fastify 启动完成 / 关闭时驱动 D 的事件基础设施与通知运行时。
  app.addHook('onReady', async () => {
    await infrastructure.start()
    try {
      await notificationRuntime.start()
    } catch (error) {
      // 失败 log 但**不吞**整体异常：启动失败即让应用启动失败（fail-fast）。
      app.log.error({ err: error }, '通知运行时启动失败')
      throw error
    }
  })
  app.addHook('onClose', async () => {
    await notificationRuntime.stop()
    await infrastructure.stop()
  })

  // FS 开工守卫窄端口（#13）：显式装配 `src/modules/task/rules.ts` 的**同一**守卫实现，
  // 供需要“进入 DOING”的其他域（当前为验收 REJECT）在同一事务内调用。不是第二套复制，
  // 也没有 no-op / 默认放行；引用方缺省时应 fail-fast。
  context.taskStartGuard = createTaskStartGuardPort<Prisma.TransactionClient>()

  registerErrorHandler(app)
  // Actor 解析：只把「当前是谁」注入 request，不做权限判定（权限一律由 can() 现查库）。
  // 采用 onRequest 钩子而非全局强制鉴权，避免误拦公开端点（如端点 1 登录）。
  registerActorResolver(app, context.prisma)
  registerRoutes(app, context)

  return app
}

/**
 * 路由集中注册表（冻结，决策 I-0 / I-9 / I-11）
 *
 * 各模块只导出路由插件，由本文件集中注册；数据库依赖通过 RouteContext 注入。
 */
import type { FastifyInstance } from 'fastify'
import type { Prisma, PrismaClient } from '@prisma/client'
import { registerAuthRoutes } from './auth/plugin.js'
import { registerAcceptanceRoutes } from './modules/acceptance/plugin.js'
import { registerAnalyticsRoutes } from './modules/analytics/plugin.js'
import { registerSensitivityRoutes } from './modules/authz/plugin.js'
import { registerProjectRoutes } from './modules/project/plugin.js'
import { registerRiskRoutes } from './modules/risk/plugin.js'
import { registerTaskRoutes } from './modules/task/routes.js'
import { registerWorkloadRoutes } from './modules/workload/plugin.js'
import { registerGanttRoutes } from './modules/gantt/plugin.js'
import { registerBoardRoutes } from './modules/board/plugin.js'
import { registerUmlRoutes } from './modules/uml/plugin.js'
import { registerWorkbenchRoutes } from './modules/workbench/plugin.js'
import { registerRequirementRoutes } from './modules/requirement/plugin.js'
import { registerAiRoutes } from './modules/ai/plugin.js'
import { registerNotificationRoutes } from './modules/notification/plugin.js'
import type { NotificationService } from './modules/notification/service.js'
import type { AiBreakdownService } from './modules/ai/service.js'
import type { GanttEventPort } from './modules/gantt/types.js'
import type { RequirementEventPort } from './modules/requirement/service.js'
import type { RiskEventPort } from './modules/risk/types.js'
import type { AcceptanceEventPort } from './modules/acceptance/types.js'
import type { TaskStartGuardPort } from './shared/task-execution.js'

export type RouteContext = {
  prisma: PrismaClient
  /**
   * #31 US-11 AI 建议服务（由 `src/app.ts` 显式组装注入）。
   *
   * 为什么用服务实例而不是在 `registerRoutes` 里现建：AI 模块的插件签名是
   * `registerAiRoutes(app, { service })`（D 的独立实现），组装（模型端口 / 仓储 / 鉴权 /
   * 故事来源）必须留在唯一组装点 `src/app.ts`，路由总表只负责注册。
   * 可选：模块测试可能只构造 `{ prisma }` 并注册部分路由；缺省时跳过 AI 路由注册。
   */
  aiService?: AiBreakdownService
  /**
   * 甘特域事件发布端口（由 `src/app.ts` 用 `createGanttEventPort` 显式组装注入）。
   *
   * 为什么用端口实例而不是在插件里现建：组装（仓储 / 事务适配器）必须留在唯一组装点
   * `src/app.ts`；路由总表只负责注册。可选：模块测试可能只构造 `{ prisma }` 并注册
   * 部分路由；缺省时 `registerGanttRoutes` 会 fail-fast 报组装缺失（不得静默跳过发布）。
   */
  ganttEvents?: GanttEventPort
  /** 需求域事件发布端口（由 `createRequirementEventPort` 组装注入，同上）。 */
  requirementEvents?: RequirementEventPort
  /**
   * 风险域事件发布端口（由 `src/app.ts` 用 `createRiskEventPort` 显式组装注入）。
   *
   * 与 `ganttEvents` / `requirementEvents` 同构：组装留在唯一组装点 `src/app.ts`，
   * 路由总表只负责注册。可选；缺省时 `registerRiskRoutes` 会 fail-fast 报组装缺失
   * （不得静默跳过发布）。事件名见 `src/modules/risk/types.ts` 的 `RiskEventName`。
   */
  riskEvents?: RiskEventPort
  /**
   * 验收域事件发布端口（由 `src/app.ts` 用 `createAcceptanceEventPort` 显式组装注入）。
   *
   * 与 `ganttEvents` / `requirementEvents` / `riskEvents` 同构：组装留在唯一组装点
   * `src/app.ts`，路由总表只负责注册。可选；缺省时 `registerAcceptanceRoutes` 会
   * fail-fast 报组装缺失（不得静默跳过发布）。
   * 事件名见 `src/modules/acceptance/types.ts` 的 `AcceptanceEventName`。
   */
  acceptanceEvents?: AcceptanceEventPort
  /**
   * #34 站内通知服务（由 `src/app.ts` 用真实仓储 / 接收者解析器 / #37 适配器显式组装）。
   *
   * 组装（仓储 / 解析器 / 事件源）留在唯一组装点 `src/app.ts`；路由总表只负责注册。
   * 缺失即 fail-fast —— **禁止** hasRoute 跳过、默认 no-op 或内存仓储回退（本批任务约束）。
   */
  notificationService?: NotificationService
  /**
   * FS 开工守卫窄端口（由 `src/app.ts` 用 `src/modules/task/rules.ts` 的**同一**守卫实现
   * 装配后注入；不是第二套复制实现，也没有 no-op / 默认放行）。
   *
   * 供需要“进入 DOING”的其他域（当前为验收 `REJECT`）在同一事务内调用，不 import
   * `src/modules/task/` 的实现（契约 I-9）。可选：模块测试可只构造 `{ prisma }`；
   * 生产 `buildApp` 始终真实注入。缺省时引用方必须 fail-fast，不得静默跳过校验。
   */
  taskStartGuard?: TaskStartGuardPort<Prisma.TransactionClient>
}

export function registerRoutes(app: FastifyInstance, context: RouteContext): void {
  app.get('/health', async () => ({ status: 'ok' }))

  // M1 身份与会话（端点 1–2）
  registerAuthRoutes(app, context)

  // M2 项目与成员（端点 3–9）
  registerProjectRoutes(app, context)

  // M3 授权与敏感可见（端点 23、30）
  registerSensitivityRoutes(app, context)

  // M4 需求层级（端点 10–22）
  registerRequirementRoutes(app, context)

  // M5 任务（端点 24–29）：24 故事任务列表 / 25 创建任务 / 26 按项目列任务 /
  // 27 任务详情 / 28 部分更新 / 29 删除。
  // 注意：端点 30（PUT /tasks/:taskId/sensitivity）唯一归属 M3，由上方
  // registerSensitivityRoutes 注册；M5 不得再注册，否则 Fastify 抛
  // FST_ERR_DUPLICATED_ROUTE 使整个应用无法构建。
  registerTaskRoutes(app, context)

  // A / US-08 个人工作台（工单 #28）：GET /me/workbench。
  // 该端点不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/us-08-workbench-api.md）。
  registerWorkbenchRoutes(app, context)

  // A / US-09 任务验收（工单 #29）：POST /tasks/:taskId/acceptance、
  // GET /tasks/:taskId/acceptances、GET /projects/:projectId/acceptance-queue。
  // 同样不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/us-09-acceptance-api.md）。
  // 注意：这两个路径与 M3 已注册的 PUT /tasks/:taskId/sensitivity 后缀不同，
  // 不与 M2 的 /projects/... 前缀冲突（Fastify 同 method+path 重复注册会抛
  // FST_ERR_DUPLICATED_ROUTE 使整个应用无法构建）。
  registerAcceptanceRoutes(app, context)

  // B / US-07 成员任务图与负载（工单 #27）：GET /projects/:projectId/workload、
  // GET /projects/:projectId/workload/:userId。
  // 同样不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-workload-design.md）。
  // 只读聚合：复用既有 project.read 权限，不新增 Action。
  registerWorkloadRoutes(app, context)

  // A / US-10 进度·健康度·风险与关闭阻断（工单 #30）：GET /projects/:projectId/dashboard、
  // GET /projects/:projectId/closure-check、风险台账（/risks 增改）与关闭 / 重开。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/us-10-progress-risk-api.md）。
  // 挂载授权：项目负责人 2026-10-18 批复第 3、4 项「改由 A 在 B 的登记范围内自行挂载」。
  registerAnalyticsRoutes(app, context)
  registerRiskRoutes(app, context)

  // B / US-06 甘特图（工单 #26）：GET /projects/:projectId/gantt。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-gantt-design.md）。
  // 只读聚合：复用既有 project.read，不新增 Action；里程碑 / 依赖写入属后续批次（#12，待公共事件端口）。
  registerGanttRoutes(app, context)

  // B / US-04 故事看板（工单 #25）：GET /projects/:projectId/board（只读三列）。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-board-design.md）。
  // 状态写入仍走既有 PATCH /stories/:storyId（端点 21），本模块不建镜像写入口。
  registerBoardRoutes(app, context)

  // #35 US-15 UML：图 / 节点 / 边与四类关联（C 的独立模块，B 只落公共注册行）。
  // 组装不需要新端口（UML 事件本期不接线）：模块直接用 `context.prisma`。
  // 写权限 `uml.write` 仅 PM、非 PM 读含 `everRestricted = false` guard，均在模块内走 can()。
  registerUmlRoutes(app, context)

  // #31 US-11 AI 建议（B 公共接入）：POST / AI 建议生成、GET 列表、POST 处置。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增；服务由 `src/app.ts` 组装后经 context 注入。
  // 三个入口均 `requireAuth`，服务端逐次走 `can()`（read 复用 project.read；生成 / 处置仅 PM）。
  if (context.aiService) registerAiRoutes(app, { service: context.aiService })

  // #34 站内通知（B 公共接入）：GET /me/notifications、GET /notifications/:id、
  // PATCH /notifications/:id/read。不在 Sprint 1 契约的 30 个端点内，属本阶段新增。
  // 服务（真实 DB 仓储 / 权威接收者解析器 / #37 适配器）由 `src/app.ts` 组装后经 context 注入；
  // **缺失即 fail-fast**：不得 hasRoute 跳过、不得默认 no-op、不得回退内存仓储（本批约束）。
  if (!context.notificationService) {
    throw new Error(
      '通知服务未组装：src/app.ts 必须注入真实 notificationService（禁止 hasRoute 跳过 / 默认 no-op / 内存仓储回退）',
    )
  }
  registerNotificationRoutes(app, context.notificationService)
}

import { z } from 'zod'
import {
  AI_SUGGESTION_LIST_LIMIT, canonicalAiJsonDigest, SHA256_CANONICAL_JSON_V1,
  type AiAccessDecision, type AiAuthorizationPort, type AiResourceRef, type AiSuggestionRepository,
} from '../../shared/ai.js'
import { AppError } from '../../shared/errors.js'
import { schedulingSuggestionSchema, type SchedulingSuggestionRecord } from './generation.js'
import { dateChangesSchema, type DateChange } from './schemas.js'
import type { SchedulingSourceResult } from './source.js'
import type { SchedulingVerification, SchedulingVerificationContext } from './verification.js'

const id = z.string().trim().min(1)
const identity = { projectId: id, suggestionId: id }
const note = z.string().trim().min(1).max(2000)
export const dispositionSchema = z.discriminatedUnion('status', [
  z.object({ ...identity, requestId: id, status: z.literal('ACCEPTED'), note: note.optional() }).strict(),
  z.object({ ...identity, requestId: id, status: z.literal('MODIFIED'), note, changes: dateChangesSchema }).strict(),
  z.object({ ...identity, requestId: id, status: z.literal('REJECTED'), note }).strict(),
])
export type SchedulingDisposition = z.infer<typeof dispositionSchema>
export type SchedulingAuditEntry = {
  projectId: string; suggestionId: string; actorUserId: string; requestId: string
  status: SchedulingDisposition['status']; reason: string | null; at: string
