export function orderedChanges(changes: readonly DateChange[]) {
  return [...changes].map(({ taskId, planStart, planEnd }) => ({ taskId, planStart, planEnd }))
    .sort((a, b) => a.taskId < b.taskId ? -1 : a.taskId > b.taskId ? 1 : 0)
